  select c.id, 'grammar', 16, $q$KG16$q$, $q$16. Present Perfect Tense$q$, $q$Hozirgi tugallangan zamon · 200 ta test$q$, 16, $q${"intro":{"what":"Present Perfect — o‘tmishda bo‘lgan, lekin natijasi hozir muhim bo‘lgan ish; vaqti aytilmaydi: I have lost my key.","when":[],"structures":[],"rules":[],"signal_words":[],"topics":[{"name":"Present Perfect: form","name_uz":"Tuzilishi","summary":"have / has + V3 (fe’lning 3-shakli). I / you / we / they → have; he / she / it → has.","usage":[{"text":"Natijasi hozir ko‘rinib turgan ish.","example":{"en":"I have broken my pen.","uz":"Ruchkamni sindirib qo‘ydim (hozir sinik)."}},{"text":"Hayotiy tajriba (qachonligi muhim emas).","example":{"en":"She has been to Paris.","uz":"U Parijda bo‘lgan."}},{"text":"Hozirgacha davom etayotgan holat (for / since).","example":{"en":"We have lived here for five years.","uz":"Biz bu yerda besh yildan beri yashaymiz."}}],"structure":[{"type":"+","formula":"subject + have / has + V3","example":{"en":"He has finished his homework.","uz":"U uy vazifasini tugatdi."}},{"type":"-","formula":"subject + haven’t / hasn’t + V3","example":{"en":"I haven’t seen this film.","uz":"Men bu filmni ko‘rmaganman."}},{"type":"?","formula":"Have / Has + subject + V3?","example":{"en":"Have you done it?","uz":"Qildingmi?"}},{"type":"short","formula":"Yes, I have. / No, she hasn’t.","example":{"en":"Has he called? — No, he hasn’t.","uz":"U qo‘ng‘iroq qildimi? — Yo‘q."}}],"signals":[],"tip":"V3 ni yodlang: go – went – gone, see – saw – seen, eat – ate – eaten."},{"name":"already, yet, just, ever, never","name_uz":"Signal so‘zlar","summary":"already, just, ever, never — have / has va V3 orasida. yet — gap oxirida (inkor va so‘roq).","usage":[{"text":"already — allaqachon.","example":{"en":"I have already eaten.","uz":"Men allaqachon ovqatlandim."}},{"text":"just — hozirgina.","example":{"en":"She has just arrived.","uz":"U hozirgina keldi."}},{"text":"yet — hali (inkor / so‘roq oxirida).","example":{"en":"Have you finished yet?","uz":"Tugatdingmi?"}},{"text":"ever / never — hech / hech qachon.","example":{"en":"Have you ever seen a lion? — I have never seen a lion.","uz":"Hech sher ko‘rganmisan? — Hech qachon ko‘rmaganman."}}],"structure":[],"signals":[{"en":"already","uz":"allaqachon"},{"en":"just","uz":"hozirgina"},{"en":"yet","uz":"hali"},{"en":"ever","uz":"hech (so‘roqda)"},{"en":"never","uz":"hech qachon"}],"tip":"never bilan fe’l inkor bo‘lmaydi: I have never seen (I haven’t never — XATO)."},{"name":"for and since","name_uz":"for va since","summary":"for + davomiylik (for two years); since + boshlanish nuqtasi (since 2020, since Monday).","usage":[{"text":"for — qancha vaqtdan beri.","example":{"en":"I have known her for ten years.","uz":"Uni o‘n yildan beri taniyman."}},{"text":"since — qachondan beri.","example":{"en":"I have known her since 2015.","uz":"Uni 2015-yildan beri taniyman."}}],"structure":[],"signals":[],"tip":"Savol: How long have you lived here? — For 3 years. / Since 2022."}],"mistakes":[{"wrong":"He have finished.","right":"He has finished.","why":"he → has."},{"wrong":"I have went there.","right":"I have gone there.","why":"have + V3 (gone)."},{"wrong":"I have seen him yesterday.","right":"I saw him yesterday.","why":"yesterday → Past Simple."},{"wrong":"I haven’t finished already.","right":"I haven’t finished yet.","why":"Inkorda yet."},{"wrong":"I have lived here since five years.","right":"I have lived here for five years.","why":"Davomiylik → for."}]},"parts":[],"translations":[],"test":[{"type":"mc","q":"We have ___ in the garden. (sleep)","options":["slept","sleeping","sleep","sleeped"],"part":0},{"type":"mc","q":"My parents have ___ at the party. (dance)","options":["dancing","danced","danceed","dance"],"part":0},{"type":"mc","q":"speak (gapirmoq) → V3: ___","options":["spoken","speaking","speaked","spoke"],"part":0},{"type":"mc","q":"win (yutmoq) → V3: ___","options":["won","wined","winning","win"],"part":0},{"type":"mc","q":"make (yasamoq) → V3