  select c.id, 'grammar', 18, $q$KG18$q$, $q$18. Prepositions of time and place. Prepositions of movement$q$, $q$Vaqt, joy va harakat predloglari · 200 ta test$q$, 18, $q${"intro":{"what":"Predloglar — qachon (vaqt), qayerda (joy) va qayerga (harakat) ekanini ko‘rsatadi.","when":[],"structures":[],"rules":[],"signal_words":[],"topics":[{"name":"Prepositions of time: in, on, at","name_uz":"Vaqt predloglari","summary":"at — aniq vaqt (soat); on — kun va sana; in — oy, yil, fasl, kunning qismi.","usage":[{"text":"at + soat, at night, at the weekend, at noon.","example":{"en":"The film starts at 7 o’clock.","uz":"Film soat 7 da boshlanadi."}},{"text":"on + hafta kuni, sana, bayram kuni.","example":{"en":"My birthday is on 5th May.","uz":"Tug‘ilgan kunim 5-mayda."}},{"text":"in + oy, yil, fasl, in the morning / afternoon / evening.","example":{"en":"We go to the sea in summer.","uz":"Yozda dengizga boramiz."}}],"structure":[],"signals":[{"en":"at 5 o’clock / at night","uz":"soat 5 da / tunda"},{"en":"on Monday / on 1st June","uz":"dushanba kuni / 1-iyunda"},{"en":"in July / in 2020 / in winter","uz":"iyulda / 2020-yilda / qishda"}],"tip":"in the morning, LEKIN on Monday morning (aniq kun bo‘lsa — on)."},{"name":"Prepositions of place","name_uz":"Joy predloglari","summary":"in — ichida (shahar, xona, quti); on — ustida, sirtida (stol, devor, qavat); at — nuqta / joy (at home, at school, at the bus stop).","usage":[{"text":"in","example":{"en":"The pen is in the box.","uz":"Ruchka qutida."}},{"text":"on","example":{"en":"The pen is on the desk.","uz":"Ruchka partada."}},{"text":"at","example":{"en":"I’m at home.","uz":"Men uydaman."}},{"text":"under, behind, next to, between, in front of, opposite, above, near.","example":{"en":"The cat is under the table.","uz":"Mushuk stol ostida."}}],"structure":[],"signals":[],"tip":"between — ikki narsa o‘rtasida: between the bank and the shop."},{"name":"Prepositions of movement","name_uz":"Harakat predloglari","summary":"into / out 