  insert into public.practice_topics (course_id, kind, unit, code, title, title_uz, sort_order, content)
  select c.id, 'grammar', 19, $q$KG19$q$, $q$19. Future Simple Tense. Be going to and Present Continuous$q$, $q$Kelasi zamon: will, be going to, Present Continuous · 200 ta test$q$, 19, $q${"intro":{"what":"Kelajak haqida gapirishning uch yo‘li: will, be going to va Present Continuous.","when":[],"structures":[],"rules":[],"signal_words":[],"topics":[{"name":"Future Simple: will","name_uz":"will","summary":"will + asl fe’l. Bashorat (I think …), gapirish paytidagi qaror, taklif va va’da uchun. Hamma ega bilan bir xil.","usage":[{"text":"Bashorat (fikr).","example":{"en":"I think it will rain tomorrow.","uz":"Menimcha, ertaga yomg‘ir yog‘adi."}},{"text":"Darhol qaror.","example":{"en":"The phone is ringing. I’ll answer it.","uz":"Telefon jiringlayapti. Men olaman."}},{"text":"Taklif va va’da.","example":{"en":"I’ll help you. I won’t forget.","uz":"Senga yordam beraman. Unutmayman."}}],"structure":[{"type":"+","formula":"subject + will (’ll) + verb","example":{"en":"She will come.","uz":"U keladi."}},{"type":"-","formula":"subject + won’t + verb","example":{"en":"They won’t be late.","uz":"Ular kechikmaydi."}},{"type":"?","formula":"Will + subject + verb?","example":{"en":"Will you help me?","uz":"Yordam berasanmi?"}}],"signals":[{"en":"tomorrow / next week / in two days","uz":"ertaga / keyingi hafta / ikki kundan keyin"},{"en":"I think / I’m sure / maybe / probably","uz":"menimcha / ishonaman / balki / ehtimol"}],"tip":"“She will comes”, “I will to go” — XATO. will + asl fe’l."},{"name":"Be going to","name_uz":"Reja va dalil","summary":"am / is / are + going to + asl fe’l. Oldindan qilingan reja yoki ko‘rinib turgan dalilga asoslangan bashorat.","usage":[{"text":"Oldindan reja.","example":{"en":"I’m going to visit my grandma on Sunday.","uz":"Yakshanba buvimnikiga bormoqchiman."}},{"text":"Dalil bor.","example":{"en":"Look at the clouds! It’s going to rain.","uz":"Bulutlarga qara! Yomg‘ir yog‘adi."}}],"structure":[{"type":"+","formula":"am / is / are + going to + ver