-- 20. Adjectives — Adverbs — Comparatives
with c as (select id from public.courses where name = $q$Kids (Prezident maktabi)$q$),
t as (
  insert into public.practice_topics (course_id, kind, unit, code, title, title_uz, sort_order, content)
  select c.id, 'grammar', 20, $q$KG20$q$, $q$20. Adjectives — Adverbs — Comparatives$q$, $q$Sifat, ravish, qiyosiy va orttirma daraja · 200 ta test$q$, 20, $q${"intro":{"what":"Sifat otni tasvirlaydi (a fast car), ravish fe’lni tasvirlaydi (he runs fast). Sifatlarning qiyosiy (bigger) va orttirma (the biggest) darajalari bor.","when":[],"structures":[],"rules":[],"signal_words":[],"topics":[{"name":"Adjectives and adverbs","name_uz":"Sifat va ravish","summary":"Sifat — ot oldida yoki to be dan keyin. Ravish — fe’ldan keyin, “qanday?” savoliga javob. Ko‘pincha sifat + -ly.","usage":[{"text":"Sifat.","example":{"en":"She is a careful driver.","uz":"U ehtiyotkor haydovchi."}},{"text":"Ravish.","example":{"en":"She drives carefully.","uz":"U ehtiyotkorona haydaydi."}},{"text":"Istisnolar: good → well, fast → fast, hard → hard.","example":{"en":"He plays football well.","uz":"U futbolni yaxshi o‘ynaydi."}}],"structure":[{"type":"+","formula":"quick → quickly, happy → happily, easy → easily","example":{"en":"Speak quietly, please.","uz":"Iltimos, sekin gapiring."}}],"signals":[],"tip":"“He speaks English good” — XATO. He speaks English well."},{"name":"Comparatives","name_uz":"Qiyosiy daraja","summary":"Ikki narsani qiyoslash: qisqa sifat + -er + than; uzun sifat: more + sifat + than.","usage":[{"text":"-er: tall → taller, nice → nicer, big → bigger, happy → happier.","example":{"en":"Ali is taller than Vali.","uz":"Ali Validan baland."}},{"text":"more: beautiful → more beautiful.","example":{"en":"This book is more interesting than that one.","uz":"Bu kitob u kitobdan qiziqroq."}},{"text":"Istisno: good → better, bad → worse, far → farther.","example":{"en":"Your mark is better than mine.","uz":"Sening bahoing menikidan yaxshiroq."}},{"text":"as … as — teng; not as … as — teng emas.","example":{"en":"I’m not as tall as my brother.","uz":"Men akamdek baland emasman."}}],"structure":[{"type":"+","formula":"A + is + adj-er / more adj + than + B","example":{"en":"A car is fa